import{_ as e,o as t,c,a4 as l}from"./chunks/framework.vNSRaLQv.js";const s=JSON.parse('{"title":"古诗词","description":"","frontmatter":{"title":"古诗词","layout":"doc"},"headers":[],"relativePath":"notes/index.md","filePath":"notes/index.md"}'),p={name:"notes/index.md"};function u(k,o,b,q,a,n){return t(),c("div",null,[...o[0]||(o[0]=[l("<blockquote><p>德玛西亚，人人皆可称王！</p></blockquote><blockquote><p>永别了，牢笼！</p></blockquote><blockquote><p>忽有狂徒夜磨刀，帝星飘摇荧惑高。</p></blockquote><blockquote><p>人之生矣有贵贱，贵人长为天恩眷？</p></blockquote><blockquote><p>待到秋来九月八，我花开后百花杀。</p></blockquote><blockquote><p>冲天香阵透长安，满城尽带黄金甲。</p></blockquote><blockquote><p>屠龙者终成恶龙。</p></blockquote><blockquote><p>王权没有永恒。</p></blockquote><blockquote><p>龙潜海角恐惊天。</p></blockquote><blockquote><p>王侯将相，宁有种乎！</p></blockquote><blockquote><p>苍天已死，黄天当立。</p></blockquote><blockquote><p>他时若遂凌云志，敢笑黄巢不丈夫。</p></blockquote><blockquote><p>此去泉台招旧部，旌旗十万斩阎罗。</p></blockquote><blockquote><p>大丈夫当如是也！</p></blockquote><blockquote><p>彼可取而代之。</p></blockquote><blockquote><p>燕雀安知鸿鹄之志？</p></blockquote><blockquote><p>我自横刀向天笑，去留肝胆两昆仑。</p></blockquote><blockquote><p>侯非侯，王非王，千乘万骑归莽山。</p></blockquote><blockquote><p>一将功成万骨枯。</p></blockquote><blockquote><p>上帝已死。</p></blockquote><blockquote><p>宁为玉碎，不为瓦全。</p></blockquote><blockquote><p>不患寡而患不均，不患贫而患不安。</p></blockquote><blockquote><p>富贵不还乡，如锦衣夜行。</p></blockquote><blockquote><p>力拔山兮气盖世。</p></blockquote><blockquote><p>天地不仁，以万物为刍狗。</p></blockquote><blockquote><p>朱门酒肉臭，路有冻死骨。</p></blockquote><blockquote><p>路漫漫其修远兮，吾将上下而求索。</p></blockquote><blockquote><p>朝闻道，夕死可矣。</p></blockquote><blockquote><p>问苍茫大地，谁主沉浮？</p></blockquote><blockquote><p>为有牺牲多壮志，敢教日月换新天。</p></blockquote><blockquote><p>宁教我负天下人，休教天下人负我。</p></blockquote><blockquote><p>有心杀贼，无力回天。</p></blockquote><blockquote><p>大风起兮云飞扬，威加海内兮归故乡，安得猛士兮守四方。</p></blockquote><blockquote><p>老骥伏枥，志在千里。</p></blockquote><blockquote><p>道生一，一生二，二生三，三生万物。</p></blockquote><blockquote><p>道可道，非常道；名可名，非常名。</p></blockquote><blockquote><p>女人和小孩都可以粗心大意，但男人不行。</p></blockquote><blockquote><p>我命由我不由天。</p></blockquote><blockquote><p>从来就没有什么救世主，也不靠神仙皇帝。</p></blockquote><blockquote><p>要为真理而斗争。</p></blockquote><blockquote><p>星星之火，可以燎原。</p></blockquote><blockquote><p>恐惧是生物的本能，勇敢是人类的赞歌。</p></blockquote><blockquote><p>一切恐惧来源于火力不足。</p></blockquote><blockquote><p>得救之道，就在其中。</p></blockquote><blockquote><p>安能摧眉折腰事权贵，使我不得开心颜！</p></blockquote><blockquote><p>我欲因之梦吴越，一夜飞度镜湖月。</p></blockquote><blockquote><p>天若有情天亦老，人间正道是沧桑。</p></blockquote><blockquote><p>雄关漫道真如铁，而今迈步从头越。</p></blockquote><blockquote><p>大盗亦有道。</p></blockquote><blockquote><p>当你长久凝视深渊时，深渊也在凝视你。</p></blockquote><blockquote><p>但使龙城飞将在，不教胡马度阴山。</p></blockquote><blockquote><p>明犯强汉者，虽远必诛。</p></blockquote><blockquote><p>黄沙百战穿金甲，不破楼兰终不还。</p></blockquote><blockquote><p>想当年，金戈铁马，气吞万里如虎。</p></blockquote><blockquote><p>只要我做到最好，谁也赢不了我。</p></blockquote><blockquote><p>壮志饥餐胡虏肉，笑谈渴饮匈奴血。</p></blockquote><blockquote><p>驾长车，踏破贺兰山缺。</p></blockquote><blockquote><p>日月终销毁，天地同枯槁。</p></blockquote><blockquote><p>和平是最大的谎言。</p></blockquote><blockquote><p>像英雄一样战斗，或者像懦夫一样死去。</p></blockquote><blockquote><p>我不是要与你为敌，我是要与世界为敌。</p></blockquote><blockquote><p>即使是一无所有的人，也能奉献出他们的生命。</p></blockquote><blockquote><p>心怀恐惧地死去，或者手染鲜血地获胜。</p></blockquote><blockquote><p>他们会像迎接英雄一般迎接你们。</p></blockquote><blockquote><p>暴力即是优雅。</p></blockquote><blockquote><p>我即是天命。</p></blockquote><blockquote><p>与人斗，其乐无穷。</p></blockquote><blockquote><p>以眼还眼，以牙还牙。</p></blockquote><blockquote><p>人不犯我，我不犯人。</p></blockquote><blockquote><p>离你的朋友近些，但离你的敌人要更近。</p></blockquote><blockquote><p>永远不要让别人知道你的真实想法。</p></blockquote><blockquote><p>一子错，满盘皆落索。</p></blockquote><blockquote><p>出来混，迟早要还的。</p></blockquote><blockquote><p>有错就要认，挨打要立正。</p></blockquote><blockquote><p>难办？那就别办了。</p></blockquote><blockquote><p>谎言不会伤人，真相才是快刀。</p></blockquote><blockquote><p>真正的大师永远怀揣着一颗学徒的心。</p></blockquote><blockquote><p>我宁愿犯错，也不愿什么都不做。</p></blockquote><blockquote><p>世界不是非黑即白，而是一道精致的灰。</p></blockquote><blockquote><p>如果一心期待他人解救，就根本不配得到自由。</p></blockquote><blockquote><p>要当心那些一无所有的人。</p></blockquote><blockquote><p>一旦见识过了真理，就再也无法忍受黑暗。</p></blockquote><blockquote><p>奋起吧，同胞们，反抗永世不渝。</p></blockquote><blockquote><p>一定要有一个巫妖王。</p></blockquote><blockquote><p>火之将熄，然而位不见王影。</p></blockquote>",85)])])}const r=e(p,[["render",u]]);export{s as __pageData,r as default};
